R["javb-checkpoint-oop"] = "public class Solution {\n    public static class Point {\n        private final int x;\n        private final int y;\n\n        public Point(int x, int y) {\n            this.x = x;\n            this.y = y;\n        }\n\n        public int getX() { return x; }\n        public int getY() { return y; }\n\n        public Point translate(int dx, int dy) {\n            return new Point(x + dx, y + dy);\n        }\n\n        public double distanceTo(Point other) {\n            int dx = this.x - other.x;\n            int dy = this.y - other.y;\n            return Math.sqrt((double) dx * dx + (double) dy * dy);\n        }\n\n        public boolean equalsPoint(Point other) {\n            return other != null && this.x == other.x && this.y == other.y;\n        }\n    }\n\n    public static Point origin() {\n        return new Point(0, 0);\n    }\n}\n";
W["javb-checkpoint-oop"] = "public class Solution {\n    public static class Point {\n        // BUG: fields are NOT final, and translate MUTATES this point\n        private int x;\n        private int y;\n\n        public Point(int x, int y) {\n            this.x = x;\n            this.y = y;\n        }\n\n        public int getX() { return x; }\n        public int getY() { return y; }\n\n        public Point translate(int dx, int dy) {\n            this.x = this.x + dx;\n            this.y = this.y + dy;\n            return this;   // returns the SAME, now-mutated object\n        }\n\n        public double distanceTo(Point other) {\n            int dx = this.x - other.x;\n            int dy = this.y - other.y;\n            return Math.sqrt((double) dx * dx + (double) dy * dy);\n        }\n\n        public boolean equalsPoint(Point other) {\n            return other != null && this.x == other.x && this.y == other.y;\n        }\n    }\n\n    public static Point origin() {\n        return new Point(0, 0);\n    }\n}\n";
R["javb-m8-shapes"] = "public class Solution {\n    public static abstract class Shape {\n        public abstract double area();\n        public abstract String name();\n    }\n\n    public static class Circle extends Shape {\n        private final double r;\n        public Circle(double r) { this.r = r; }\n        public double area() { return Math.PI * r * r; }\n        public String name() { return \"circle\"; }\n    }\n\n    public static class Rect extends Shape {\n        private final double w, h;\n        public Rect(double w, double h) { this.w = w; this.h = h; }\n        public double area() { return w * h; }\n        public String name() { return \"rect\"; }\n    }\n\n    public static double totalArea(Shape[] shapes) {\n        double total = 0;\n        for (Shape s : shapes) {\n            total += s.area();\n        }\n        return total;\n    }\n}\n";
